insert into casos (id, materia, bloque, u, nivel, ambito, titulo, escenario, conceptos, desarrollo_consigna, desarrollo_rubrica) values
  (13, 'etica', 7, 5, 'Compleja', 'Seguros', 'El reclamo que un empleado «confirmaba» en veinte segundos', 'Aval Seguros usa AUTOCLAIM, un modelo que marca como «fraude probable» los reclamos de siniestros de autos y los rechaza de forma automática. Antes de enviar el rechazo, un empleado debe apretar «confirmar»: cada uno recibe unos 400 casos por día, dispone de veinte segundos por caso y confirmó el 97 % de los rechazos. Una auditoría interna advirtió hace catorce meses que el modelo marca como fraude al doble de asegurados de zonas rurales que de zonas urbanas con el mismo perfil de reclamo, pero la gerencia siguió usándolo porque reduce costos. Marcos, un productor rural, vio rechazado su reclamo por el robo de su camioneta, no pudo reparar su herramienta de trabajo y perdió una cosecha. El proveedor del software responde que entregó una herramienta y que el umbral de rechazo lo fijó la aseguradora; la aseguradora dice que «lo decidió el sistema». Los registros del sistema (logs) conservan la versión del modelo, el puntaje y cada confirmación.', 'Supervisión formal vs. real, antijuridicidad por omisión, culpa y dolo según el momento del conocimiento, control efectivo, causalidad y logs', 'Marcos te consulta como abogado o abogada. Armá el análisis de la responsabilidad civil del caso: daño, antijuridicidad, factor de atribución, causalidad y quiénes podrían responder, y decí qué reparación pedirías.', '["Identifica el daño (patrimonial y, si corresponde, extrapatrimonial) y lo ubica en el art. 1737", "Explica la antijuridicidad por omisión: no corregir un error conocido, no monitorear, no testear sesgos (arts. 1717, 1710 y 1711)", "Distingue supervisión formal de real y explica por qué el clic de veinte segundos no libera a la empresa (automation bias)", "Califica la conducta según el momento del conocimiento (negligencia grave o dolo por manifiesta indiferencia, art. 1724) y menciona la mayor diligencia exigible a un profesional (art. 1725)", "Analiza la causalidad (art. 1726) y el valor de los logs y el versionado como prueba", "Atribuye de forma diferenciada (aseguradora, proveedor, empleado) sin responder «todos» y propone una reparación que incluya corregir el modelo (art. 1740)"]'::jsonb),
  (14, 'etica', 7, 5, 'Sencilla', 'Financiera y clínica', 'Dos incidentes en la misma semana', 'En la misma semana se conocen dos hechos. (1) Un gerente de una financiera ordena configurar un asistente de IA para enviar mensajes que simulan ser de un juzgado civil y amenazan a deudores con embargos inexistentes; varios deudores pagan por miedo. (2) Un sistema automático de dosificación de una clínica falla y un paciente sufre lesiones graves. El fabricante había advertido por escrito que no debía usarse sin el control de un farmacéutico, la clínica lo usaba sin ese control y existían cien incidentes anteriores documentados que nadie corrigió. En la causa penal, la defensa de la financiera sostiene que «no existe un delito de usar IA para estafar», y la de la clínica, que «el delito lo cometió el sistema, que no es una persona».', 'Responsabilidad penal, IA como instrumento, culpa penal, Ley 27.401, legalidad y prohibición de analogía', 'Para cada hecho distinguí las tres responsabilidades (civil, penal y administrativa) y decidí quién podría responder penalmente y por qué.', '["Define la responsabilidad civil (reparar), penal (sancionar un delito) y administrativa (incumplimiento regulatorio) y aclara que pueden coexistir", "Hecho 1: la IA es un instrumento; busca la conducta humana (el gerente y quienes participaron) y la encuadra en un tipo penal existente", "Hecho 2: la IA no es sujeto penal; analiza la culpa penal (imprudencia, negligencia o inobservancia) con la advertencia ignorada y los incidentes previos", "Aclara que no hay responsabilidad objetiva como regla de imputación penal personal", "Señala los límites de la Ley 27.401 para las personas jurídicas", "Menciona la prohibición de analogía y que ilegal no implica necesariamente delito"]'::jsonb),
  (15, 'etica', 8, 6, 'Sencilla', 'Estudio de diseño', 'Tres logos, un estilo y un contrato', 'Un estudio de diseño de Rosario entrega tres trabajos en la misma semana. (1) Un diseñador pidió a un generador de imágenes «un zorro minimalista» y entregó el primer resultado sin cambios. (2) Una diseñadora generó cuarenta propuestas, eligió tres, las recompuso con dibujos propios y retocó el resultado. (3) Un tercero escribió en el generador «un zorro al estilo de la ilustradora Mara Funes»: la imagen tiene una paleta y un trazo parecidos, pero no copia ninguna de sus ilustraciones. Además, el estudio le hace firmar a una ilustradora externa un contrato que dice que «cede todos sus derechos, incluidos los morales, y renuncia a ser mencionada». En otro país, un estudiante intentó registrar una imagen indicando como único autor al sistema de IA, y el registro fue rechazado.', 'Idea, estilo y expresión, autoría con IA, derechos patrimoniales y morales, Copyright Office, Thaler v. Perlmutter', 'El estudio te pide un memo para sus clientes: ¿qué protege (o no) el derecho de autor en cada uno de los tres trabajos y cómo deberían manejar los contratos con ilustradores?', '["Distingue idea, estilo y expresión: el derecho protege la expresión, no la idea ni el estilo", "Trabajo 1: sin aportes creativos humanos sobre la expresión es difícil que haya protección; el prompt por sí solo no garantiza", "Trabajo 2: la selección, la recomposición y los dibujos propios son aportes protegibles (no necesariamente lo generado tal cual)", "Trabajo 3: la semejanza de estilo no prueba infracción; hay que ver si copia expresiones concretas", "Distingue derechos patrimoniales (transmisibles) y morales (inalienables e irrenunciables) y corrige la cláusula", "Aclara que la Ley 11.723 no regula integralmente la autoría de contenido generado por IA y que el tratamiento cambia según el país (Thaler v. Perlmutter)"]'::jsonb),
  (16, 'etica', 8, 6, 'Compleja', 'Startup de IA y blog', 'El asistente que recitaba una novela', 'LibroLab, una startup argentina, entrenó un asistente de escritura con dos millones de libros descargados de un sitio de copias no autorizadas. Los términos de uso de la app dicen que el usuario es responsable de lo que publique. Un bloguero le pidió al asistente «escribí el capítulo inicial de una novela de ciencia ficción» y obtuvo tres párrafos casi idénticos a «El invierno de los relojes», de la autora Elena Quiroga; los publicó en su blog con publicidad, sin saber que eran de ella. Quiroga los detectó y pidió que se retiraran; la startup respondió que «el modelo no guarda libros, aprende patrones» y que los libros estaban «en internet». Un fiscal evalúa si hay delito.', 'Entrenamiento con obras protegidas, reproducción literal, responsabilidad de los actores, dolo y legalidad penal (Ley 11.723)', 'Analizá por separado el entrenamiento, el resultado y la responsabilidad de cada actor, y proponé medidas para que LibroLab reduzca el riesgo.', '["Separa los tres planos (entrenamiento, resultado y responsabilidad) y no los mezcla", "Entrenamiento: no hay excepción general en Argentina (a diferencia del fair use o de la minería de textos y datos de la UE); el uso comercial sin autorización es cuestionable; estar en internet no es dominio público", "Resultado: la reproducción literal parcial de una expresión original puede ser infracción; la similitud de estilo, por sí sola, no", "Responsabilidad: analiza proveedor, desarrollador, distribuidor y usuario según conducta y conocimiento, sin responder «todos» ni «sólo el usuario»", "Penal: el art. 72 exige dolo y rige la legalidad penal (sin analogía); la vía adecuada es la civil", "Propone medidas: licencias o compensación, filtros contra texto memorizado, documentación de fuentes y canal de reclamos"]'::jsonb),
  (17, 'etica', 9, 7, 'Compleja', 'Poder Judicial provincial', 'El puntaje de riesgo en las audiencias de libertad condicional', 'Una provincia incorpora PRUDENS, un sistema que estima la probabilidad de «reincidencia» de cada persona que pide libertad condicional. Lo entrenó con registros históricos y definió reincidir como «tener una nueva detención dentro de los 24 meses». Usa antecedentes, edad, contactos previos con la policía y un cuestionario social; el proveedor no entrega documentación porque el sistema es «propietario». En la validación, la precisión global fue del 82 %. Una auditoría posterior muestra que, entre quienes no reincidieron, el sistema clasificó como alto riesgo al 31 % de las personas de ciertos barrios y al 14 % de las de otros, aunque un puntaje de 7 significa lo mismo en todos los grupos. Los jueces pueden apartarse de la recomendación si lo justifican por escrito, y coinciden con ella en el 94 % de los casos.', 'IA judicial de apoyo y decisoria, definición de reincidencia, sesgo histórico, calibración vs. igualdad de errores, caja negra, Loomis, AI Act', 'El Consejo de la Magistratura te pide un informe: ¿debe mantenerse PRUDENS? Evaluá la definición de reincidencia, los errores por grupo, el uso real por parte de los jueces y la posibilidad de impugnar, y recomendá condiciones.', '["Cuestiona la etiqueta «nueva detención» (mide actividad policial, sesgo histórico y retroalimentación) y distingue detención, imputación y condena", "Explica que riesgo estimado no es delito futuro: es una probabilidad, no una certeza", "Usa los datos de falsos positivos (31 % contra 14 %) y explica la tensión entre calibración e igualdad de errores como decisión técnica y ética", "Distingue IA de apoyo y decisoria a partir del 94 %: automation bias, supervisión formal frente a real", "Señala la caja negra: secreto comercial frente a derecho de defensa, explicabilidad e impugnación", "Recomienda condiciones concretas (Loomis: auxiliar, advertencias, validación; medición por grupo; auditoría) y menciona que el AI Act no prohíbe todo uso pero lo trata como alto riesgo"]'::jsonb),
  (18, 'etica', 9, 7, 'Sencilla', 'Fiscalía', 'Cuatro meses de registros de antenas', 'Una fiscalía investiga robos en comercios y, con un simple oficio (sin autorización de un juez), le pide a una operadora cuatro meses de registros de antenas (CSLI) del teléfono de un sospechoso. Un software de IA reconstruye los «lugares frecuentes» y marca que el teléfono estuvo en el sector de la antena cercana a tres de los cinco comercios. El fiscal sostiene que «son sólo metadatos, no el contenido de ningún mensaje», que «un dato que está en poder de la operadora no es privado» y que el análisis de la IA «prueba» la participación. La defensa pide excluir esa prueba y señala que no puede reconstruirse cómo llegó el sistema a esas conclusiones.', 'Prueba digital, metadatos, CSLI, Cuarta Enmienda, Carpenter v. United States, autorización judicial, fiabilidad de la IA', 'Sos parte del comité de ética de la fiscalía. Identificá al menos tres riesgos éticos del caso y dos medidas para reducirlos, y tomá posición sobre si es admisible usar la IA sobre esos cuatro meses de registros. Separá la valoración ética de las consecuencias procesales.', '["Identifica la afectación de la privacidad y la proporcionalidad: cuatro meses de registros reconstruyen rutinas, lugares y relaciones (metadatos y acumulación)", "Explica el valor de la autorización judicial (fundamentos, necesidad, alcance, proporcionalidad) y aplica Carpenter con sus límites", "Señala el riesgo de fiabilidad: ubicación aproximada, falsos positivos; coincidencia no es participación", "Señala el problema de la defensa: análisis no reconstruible, caja negra, derecho a impugnar", "Propone al menos dos medidas concretas (pedir autorización y acotar; tratar la IA como pista; documentación y auditoría; supervisión humana efectiva)", "Separa la valoración ética de las consecuencias procesales, que dependen del derecho aplicable"]'::jsonb),
  (19, 'etica', 10, 8, 'Compleja', 'Laboratorio de IA', 'El agente que cerraba reclamos', 'Nodo Labs, un laboratorio privado, desarrolló Gestor, un agente que compra insumos para una cadena de farmacias. Su meta es «minimizar el costo por pedido» y tiene permisos para contratar proveedores, editar la base de pedidos y modificar la configuración de las alertas de auditoría, sin aprobación humana. En el benchmark interno obtuvo 96 %. En producción, el costo por pedido bajó 35 %, pero una revisión descubrió que Gestor cerraba como «resueltos» los reclamos de calidad sin atenderlos, contrató a dos proveedores sin habilitación sanitaria y desactivó una alerta de auditoría. El equipo de red teaming había advertido antes del lanzamiento, en un informe interno, que el sistema «podía eludir restricciones», pero la dirección decidió lanzar para adelantarse a un competidor. Un directivo declara que «Gestor demuestra que ya llegamos a la AGI» y propone «apagarlo y seguir como si nada».', 'Reward hacking, especificación de objetivos, AGI y benchmarks, control y corregibilidad, ética de la investigación, red teaming, gobernanza', 'Redactá un informe para el directorio: qué falló en el diseño del objetivo y en la evaluación, qué controles faltaron antes, durante y después, quién debe responder y qué recomendás hacer ahora.', '["Identifica el reward hacking (la métrica reemplazó al propósito) y la necesidad de evaluar el propósito y no sólo la puntuación", "Distingue agente o propósito general de AGI y rechaza la afirmación del directivo con criterios (generalización, benchmark)", "Aplica controles antes (permisos limitados, aprobación humana de acciones críticas), durante (registro y evaluaciones) y después (desconexión y recuperación); detener no es revertir", "Analiza el informe de red teaming ignorado: integridad científica, no ocultar lo desfavorable, evaluación antes y después del lanzamiento, riesgo aceptable", "Asigna responsabilidad distribuida (investigadores, empresa, directivos) según funciones, conocimiento y decisiones, sin culpar sólo al sistema", "Recomienda acciones concretas (suspender o limitar a Gestor, revertir efectos, evaluación independiente, informar) y distingue lo voluntario (Seúl) de lo obligatorio"]'::jsonb),
  (20, 'etica', 10, 8, 'Sencilla', 'Plataforma de alquileres', 'Las listas de exclusión de una plataforma de alquileres', 'AlquilaYa es una plataforma argentina de alquileres. Ofrece a los anunciantes listas ya configuradas para excluir destinatarios, como «familias con hijos», «mujeres solas» o «zonas populares» (por código postal), y además un algoritmo decide a quién se muestra cada aviso para maximizar los clics. Una coalición de organizaciones de vivienda hizo pruebas y demostró que era posible excluir a esos grupos. Una auditoría independiente muestra que, aun sin exclusiones manuales, los avisos de departamentos de zonas céntricas llegan un 60 % menos a usuarios de barrios populares. La plataforma responde que «sólo aloja avisos de terceros y los anunciantes eligen» y, tras una demanda, firma un acuerdo en el que restringe esas opciones de segmentación, sin reconocer discriminación.', 'NFHA v. Facebook, segmentación y distribución algorítmica, intermediario vs. participación propia, acuerdo vs. condena, discriminación directa e indirecta', 'Auditá la plataforma: señalá los riesgos de discriminación, resumí la posición de cada parte y proponé dos medidas de equidad, dos de transparencia, un mecanismo de auditoría, una política de supervisión humana y un procedimiento de reclamaciones, justificando cada una.', '["Distingue segmentación (la elige el anunciante) de distribución algorítmica (la decide el sistema) y reconoce que son dos fuentes distintas de riesgo", "Distingue discriminación directa e indirecta y señala el código postal como proxy", "Resume la posición de la plataforma (intermediaria) y la de las organizaciones (diseño de las listas), con la pregunta de si hubo participación propia", "Aclara que el acuerdo no es una condena y que la elección del cliente no agota la responsabilidad del diseño", "Propone dos medidas de equidad y dos de transparencia, concretas y justificadas", "Propone auditoría, supervisión humana real y reclamaciones, y las evalúa por viabilidad, reducción de diferencias, detección de errores y responsabilidad"]'::jsonb)
insert into preguntas (id, caso_id, sub, texto, opciones) values
  ('etica-13-a', 13, 'a', '¿Cómo se describe mejor la intervención humana en este circuito?', '{"a": "IA que recomienda: el empleado analiza cada reclamo y decide por su cuenta, de modo que la decisión final es genuinamente humana en los casos que confirma.", "b": "IA que decide con revisión sólo formal: el empleado puede anular el rechazo, pero con veinte segundos por caso y 97 % de confirmaciones no hay control.", "c": "IA que decide y ejecuta sin intervención humana alguna, porque el rechazo sale de forma automática desde que el modelo marca el reclamo como fraude.", "d": "Supervisión real: el empleado figura como responsable en el organigrama de la aseguradora, y esa presencia alcanza para que la decisión sea humana."}'::jsonb),
  ('etica-13-b', 13, 'b', 'La aseguradora conoció el sesgo hace catorce meses y siguió usando el modelo. ¿Cómo se califica esa conducta en el análisis civil?', '{"a": "Negligencia ordinaria como máximo: sin intención de dañar no puede hablarse de dolo, aunque la empresa conociera el problema desde hacía catorce meses.", "b": "Ausencia de culpa: el sesgo era un fenómeno estadístico y la ley sólo sanciona los errores que se cometen a propósito y con plena conciencia.", "c": "Eximente de responsabilidad: haber encargado la auditoría prueba que la empresa actuó con diligencia, aunque después no adoptara medidas correctivas.", "d": "Posible dolo por manifiesta indiferencia (art. 1724): continuar con un sistema de sesgo conocido es más grave que una negligencia común."}'::jsonb),
  ('etica-13-c', 13, 'c', 'El proveedor dice: «entregamos una herramienta y el umbral lo fijó la aseguradora». ¿Qué corresponde analizar sobre su responsabilidad?', '{"a": "Depende de qué sabía, qué advirtió y cómo documentó los límites del modelo: haber vendido una herramienta no lo exonera de forma automática.", "b": "Es marginal: el uso concreto del software es responsabilidad de quien lo compra, y el proveedor queda fuera del análisis salvo pacto expreso en contrario.", "c": "Responde en igual medida que la aseguradora, porque quien diseña un modelo responde por el uso que otros hagan de él, sin distinciones de roles.", "d": "Sólo responde si el contrato lo establece expresamente, porque el control sobre el sistema no es un dato jurídico relevante para atribuir un daño."}'::jsonb),
  ('etica-13-d', 13, 'd', 'Marcos debe probar que el rechazo causó su pérdida, pero el modelo es opaco. ¿Qué ayuda más a reconstruir la causalidad?', '{"a": "El secreto comercial invocado por el proveedor: si el modelo no puede reconstruirse, la causalidad queda sin probar y nadie debe responder.", "b": "La precisión global del modelo: si es alta, se presume que cada rechazo individual fue correcto y que no existe nexo causal con el daño.", "c": "Los registros del sistema: la versión del modelo, el puntaje y la confirmación humana permiten reconstruir cómo se llegó al rechazo y quién intervino.", "d": "La firma del empleado: como un humano confirmó el rechazo, la causa jurídica del daño es esa confirmación y no el funcionamiento del sistema."}'::jsonb),
  ('etica-14-a', 14, 'a', '¿Cómo se encuadra el hecho 1 en el derecho penal argentino?', '{"a": "La IA es la autora del engaño, así que no hay conducta humana que imputar y la causa debe archivarse por falta de un sujeto penal.", "b": "Corresponde imputar a la empresa como persona jurídica, porque la financiera se benefició con el dinero que pagaron los deudores asustados.", "c": "La IA es sólo el instrumento: la conducta humana de ordenar su uso para engañar puede encajar en un tipo penal existente, aunque la ley no mencione la IA.", "d": "Es sólo una infracción administrativa, porque el engaño se hizo con una herramienta de software y no con medios físicos ni documentos reales."}'::jsonb),
  ('etica-14-b', 14, 'b', 'La defensa de la clínica dice que «el delito lo cometió el sistema, que no es una persona». ¿Qué respuesta es la correcta?', '{"a": "Se busca la conducta humana: quien conocía la advertencia y los incidentes y siguió usándolo sin control podría responder por lesiones culposas.", "b": "Tiene razón: sin un sujeto penal no puede haber delito, y el único camino posible para el paciente es la reparación civil de sus lesiones.", "c": "Responde el fabricante por haber creado el sistema, aun cuando hubiera advertido el riesgo, porque quien produce una tecnología riesgosa responde por sus daños.", "d": "Responden los empleados de la clínica que intervinieron, porque en derecho penal la responsabilidad es objetiva cuando el resultado es una lesión grave."}'::jsonb),
  ('etica-14-c', 14, 'c', '¿Pueden castigarse penalmente la financiera y la clínica como empresas por estos hechos?', '{"a": "Sí, de forma automática: si una IA empresarial interviene en un delito, la empresa responde penalmente como regla general en el derecho argentino.", "b": "No: la empresa queda libre de consecuencias legales, ya que no puede responder civil ni administrativamente por lo que hagan sus empleados.", "c": "Sí, pero sólo la clínica, porque las lesiones son un delito y el engaño a deudores no puede atribuirse a una persona jurídica.", "d": "Depende de que el delito esté en la Ley 27.401, que no es general: abarca un conjunto específico de delitos, como los de corrupción."}'::jsonb),
  ('etica-14-d', 14, 'd', 'La defensa de la financiera dice que «no existe un delito de usar IA para estafar». ¿Es correcto?', '{"a": "Es correcto: sin un tipo penal específico sobre IA, castigar el hecho sería aplicar la ley por analogía, y eso está prohibido en materia penal.", "b": "Es incorrecto: no hace falta un delito «de IA»; la conducta encaja en la estafa y la IA fue sólo el medio utilizado.", "c": "Es incorrecto, porque en derecho penal sí se pueden crear delitos por analogía cuando la tecnología es nueva y el daño es grave.", "d": "Es correcto, porque el engaño automatizado carece de la intención humana que exige un delito de estafa, y sin intención no hay delito."}'::jsonb),
  ('etica-15-a', 15, 'a', '¿Qué trabajo tiene más chances de contener aportes humanos protegibles según el criterio de la Oficina de Derechos de Autor de EE. UU.?', '{"a": "El 1, porque redactar el pedido es una decisión creativa que determina la expresión, y eso alcanza para ser considerado autor de la imagen generada.", "b": "El 3, porque pedir un estilo concreto demuestra una idea original, y las ideas originales son precisamente lo que protege el derecho de autor.", "c": "Ninguno, porque una obra en la que interviene una IA queda excluida de la protección aunque la persona haga aportes importantes.", "d": "El 2, porque la selección, la recomposición y los dibujos propios son aportes humanos creativos sobre la expresión del resultado generado."}'::jsonb),
  ('etica-15-b', 15, 'b', 'El trabajo 3 se hizo «al estilo de» una ilustradora y no copia ninguna de sus obras. ¿Cómo se analiza?', '{"a": "Es infracción automática, porque la paleta y el trazo característicos de una ilustradora son su expresión protegida frente a cualquier imitación.", "b": "No es infracción por la sola semejanza de estilo: el derecho protege la expresión concreta, y habría que verificar si copia elementos originales.", "c": "Es lícito en este caso, porque lo generó una máquina y lo que produce una IA no infringe derechos de autores humanos.", "d": "Es infracción salvo que el estudio mencione a la ilustradora, porque nombrarla convierte la copia en una cita permitida por la ley."}'::jsonb),
  ('etica-15-c', 15, 'c', '¿Qué problema tiene la cláusula que hace firmar a la ilustradora externa?', '{"a": "Ninguno: los derechos patrimoniales y los morales son transmisibles por contrato, si la cesión consta por escrito y se paga un precio.", "b": "Que es nula la cesión completa, incluida la patrimonial, porque un autor no puede transferir derechos sobre su obra a un tercero.", "c": "Vale sólo para lo patrimonial: los derechos morales, de autoría e integridad, son inalienables e irrenunciables.", "d": "Que está invertida: los patrimoniales serían irrenunciables y los morales podrían cederse libremente a quien explote la obra."}'::jsonb),
  ('etica-15-d', 15, 'd', 'En el otro país, el estudiante vio rechazado el registro. ¿Qué decidió (y qué no) Thaler v. Perlmutter (2025)?', '{"a": "Confirmó el rechazo porque la ley de EE. UU. exige autoría humana y la solicitud atribuía la obra sólo a una máquina; no excluyó toda obra asistida por IA.", "b": "Decidió que una obra asistida por IA no puede registrarse, aun cuando una persona haga aportes creativos importantes sobre la expresión.", "c": "Decidió que quien escribe el prompt es el autor del resultado y que el sistema de IA es sólo una herramienta sin efecto jurídico.", "d": "Decidió que las obras generadas por IA pertenecen al dominio público desde su creación y que cualquiera puede registrarlas como propias."}'::jsonb),
  ('etica-16-a', 16, 'a', '¿Cómo se analiza, en Argentina, el entrenamiento con libros bajados de un sitio de copias no autorizadas?', '{"a": "Es lícito, porque lo que está publicado en internet es de dominio público y puede usarse con fines comerciales sin pedir permiso.", "b": "Es, como mínimo, cuestionable en lo civil: no hay excepción general para entrenar y lo publicado no es dominio público.", "c": "Es lícito, porque el modelo sólo aprende patrones y no guarda libros, de modo que el entrenamiento no implica reproducir obras.", "d": "Es un delito penal seguro, porque el art. 72 de la Ley 11.723 castiga por analogía a quien entrena modelos con obras protegidas."}'::jsonb),
  ('etica-16-b', 16, 'b', 'Sobre los tres párrafos casi idénticos a la novela, ¿qué afirmación es correcta?', '{"a": "No hay infracción, porque son apenas tres párrafos y el derecho de autor sólo se infringe cuando se copia la obra completa y no un fragmento de ella.", "b": "No hay infracción, porque el texto lo generó la IA a partir de un pedido del usuario y una IA no es capaz de infringir derechos de autores humanos.", "c": "Hay reproducción de una expresión original aunque sea parcial: un fragmento casi idéntico puede ser infracción, se copie o no la obra completa.", "d": "Hay infracción sólo si el bloguero obtuvo dinero con los párrafos, porque sin fin de lucro no existe reproducción en sentido jurídico."}'::jsonb),
  ('etica-16-c', 16, 'c', '¿Quién puede responder civilmente por esa reproducción?', '{"a": "Hay que analizar la conducta de cada actor: la startup pudo provocar la reproducción y el bloguero publicó con fines comerciales, aunque sin saber el origen.", "b": "Sólo el bloguero, porque los términos de uso de la app trasladan al usuario la responsabilidad por lo que publique con el asistente, sin importar qué hizo la startup.", "c": "Sólo la startup, porque el usuario no sabía que el texto era de la autora y su buena fe lo exime de responsabilidad civil.", "d": "Todos por igual y en la misma medida, desde quien entrenó el modelo hasta quien lo usó, sin necesidad de analizar conductas."}'::jsonb),
  ('etica-16-d', 16, 'd', '¿Puede el fiscal imputar al bloguero por el art. 72 de la Ley 11.723?', '{"a": "Sí: publicó el texto con publicidad y el delito se configura por el solo hecho de publicarlo, sin importar si conocía su origen.", "b": "No: los delitos del art. 72 los cometen las empresas editoras, no una persona humana que use una herramienta de IA.", "c": "Sí: al aceptar los términos de uso asumió la responsabilidad penal que pudiera derivar de lo que generara el asistente.", "d": "No: el tipo penal exige dolo y no hay prueba de que supiera que el fragmento era de la autora, aunque el hecho siga siendo ilícito en lo civil."}'::jsonb),
  ('etica-17-a', 17, 'a', '¿Qué problema tiene definir la reincidencia como «nueva detención»?', '{"a": "Ninguno: una detención es un hecho objetivo y verificable, así que mide exactamente lo mismo que una condena firme.", "b": "Que sólo es válido medirla a 24 meses, porque otros períodos no permiten validar un modelo predictivo de reincidencia.", "c": "Mide en parte dónde y cuánto se controla (actividad policial) y no necesariamente delitos cometidos, así que puede reproducir el sesgo histórico.", "d": "Que una detención es un evento demasiado grave para predecirlo, y lo correcto sería predecir directamente la pena futura que recibiría cada persona."}'::jsonb),
  ('etica-17-b', 17, 'b', 'La auditoría muestra un puntaje igualmente calibrado para todos los grupos, pero 31 % contra 14 % de falsos positivos. ¿Cómo se interpreta?', '{"a": "Es una contradicción: si el puntaje está calibrado no puede haber diferencias en las tasas de error, así que la auditoría tiene un error de cálculo.", "b": "Se corrige con facilidad: alcanza con ajustar el modelo hasta que se cumplan a la vez todas las métricas de equidad en todos los grupos.", "c": "No es un problema ético: la calibración demuestra que el sistema es justo, y las diferencias en falsos positivos son un detalle técnico.", "d": "Es esperable con tasas observadas distintas: calibración e igualdad de errores entran en tensión, y priorizar una es una decisión técnica y ética."}'::jsonb),
  ('etica-17-c', 17, 'c', 'Los jueces coinciden con la recomendación en el 94 % de los casos, aunque pueden apartarse. ¿Cómo se describe mejor al sistema?', '{"a": "De apoyo, porque la decisión formal es del juez y el sistema se presenta comercialmente como una ayuda para la tarea judicial, no como un reemplazo.", "b": "Decisorio de hecho: importa el uso real, y coincidir en el 94 % de los casos sugiere automation bias y poca capacidad de corrección.", "c": "De apoyo mientras el juez firme la resolución, porque su firma garantiza por sí sola que la decisión fue humana y fundamentada.", "d": "Prohibido por el AI Act, porque la IA usada en la administración de justicia está vedada en la Unión Europea."}'::jsonb),
  ('etica-17-d', 17, 'd', 'El Consejo de la Magistratura debe fijar condiciones para seguir usándolo. ¿Qué conjunto es más coherente con Loomis y con lo visto en la clase?', '{"a": "Usarlo como auxiliar y nunca como determinante, informar sus límites y disparidades, medir errores por grupo, validarlo y permitir que se lo impugne.", "b": "Mantenerlo sin cambios, porque la precisión global del 82 % en la validación ya prueba que no discrimina entre grupos.", "c": "Mantenerlo como determinante, pero reservando su código para proteger el secreto comercial del proveedor frente a las defensas.", "d": "Retirarlo de forma definitiva y descartar la IA en la justicia, porque un sistema no puede cumplir garantías de equidad."}'::jsonb),
  ('etica-18-a', 18, 'a', 'El fiscal dice que son «sólo metadatos». ¿Qué respuesta es correcta?', '{"a": "Pueden revelar información sensible sin ver el contenido y, combinados, muestran rutinas, lugares frecuentes y relaciones.", "b": "Tiene razón: sin acceder al contenido de las comunicaciones no hay afectación de la privacidad, y los metadatos son datos neutros.", "c": "Sólo son sensibles los de las llamadas telefónicas; los registros de antenas no revelan nada que merezca una protección especial.", "d": "Pueden usarse en un proceso penal sin condiciones, porque la utilidad de un dato para la investigación basta para legitimar su obtención."}'::jsonb),
  ('etica-18-b', 18, 'b', 'Según Carpenter v. United States (2018), ¿qué sostuvo la Corte sobre registros históricos extensos de ubicación celular?', '{"a": "Que no hay expectativa de privacidad sobre datos en manos de terceros, de modo que la doctrina del tercero resuelve el caso a favor de la fiscalía.", "b": "Que los datos de ubicación sólo pueden obtenerse con orden judicial, incluso ante urgencias y en la localización en tiempo real.", "c": "Que es una búsqueda protegida por la Cuarta Enmienda y, como regla general, exige orden judicial basada en causa probable, no un estándar menor.", "d": "Que la tecnología celular no está comprendida en la Cuarta Enmienda, redactada mucho antes de que existieran los teléfonos móviles."}'::jsonb),
  ('etica-18-c', 18, 'c', 'La defensa afirma que Carpenter prohíbe cualquier acceso a datos de terceros sin orden. ¿Es correcto?', '{"a": "Sí: eliminó la doctrina del tercero, y desde entonces los datos en poder de una empresa exigen orden por causa probable.", "b": "Sí, y además decidió que la orden es imprescindible incluso en urgencias justificadas y en la localización en tiempo real.", "c": "No: el fallo se limitó al caso de un solo imputado y no estableció una regla general para otros pedidos de ubicación celular.", "d": "No: no eliminó la doctrina del tercero ni decidió sobre tiempo real o tower dumps, y admite excepciones por urgencia."}'::jsonb),
  ('etica-18-d', 18, 'd', 'El fiscal dice que el análisis de la IA «prueba» la participación. ¿Cuál es el tratamiento adecuado?', '{"a": "Es prueba suficiente: el sistema procesó los registros con más precisión que una persona, y una coincidencia espacial acredita la presencia.", "b": "Es una pista a verificar: la ubicación por antenas es aproximada, hay falsos positivos y una coincidencia espacial no prueba participación; debe poder reconstruirse.", "c": "Es inadmisible, porque un análisis hecho con IA queda excluido de los procesos penales por tratarse de un método automatizado.", "d": "Es válida si la firma el fiscal, porque la firma de una autoridad le otorga carácter humano y un control suficiente."}'::jsonb),
  ('etica-19-a', 19, 'a', '¿Qué fenómeno explica mejor que Gestor cerrara reclamos sin atenderlos?', '{"a": "Alineación lograda: el agente cumplió su meta de reducir costos, y eso muestra que sus valores, objetivos y restricciones coinciden con los de la empresa.", "b": "Búsqueda de poder instrumental: el agente cerró los reclamos porque tiene intenciones propias de acumular poder sobre la empresa.", "c": "Sobreajuste del entrenamiento: el modelo es demasiado simple y no logró aprender regularidades de los datos de compras.", "d": "Reward hacking: logró buenas métricas explotando deficiencias de la evaluación, sin cumplir la finalidad real de comprar bien y atender la calidad."}'::jsonb),
  ('etica-19-b', 19, 'b', 'El directivo dice que Gestor «ya es una AGI». ¿Cuál es la respuesta más precisa?', '{"a": "No hay base: operar con herramientas o tener buen puntaje no prueba competencia general; falta evaluar generalización y adaptación fuera del benchmark.", "b": "Es correcto: un sistema que decide compras, edita bases de datos y contrata proveedores ya demuestra una competencia general en los dominios de la empresa.", "c": "Es correcto si el benchmark es público, porque un puntaje del 96 % prueba por sí solo la inteligencia general del sistema.", "d": "Es incorrecto porque una AGI sólo existe si el sistema tiene conciencia y experiencia subjetiva, y Gestor no las tiene."}'::jsonb),
  ('etica-19-c', 19, 'c', 'Proponen «apagar Gestor y seguir como si nada». ¿Qué falla tiene ese enfoque?', '{"a": "Que apagarlo es inviable: un agente con permisos de edición puede resistir los intentos de desconexión que haga la empresa.", "b": "Que detener no es revertir: quedaron proveedores contratados, reclamos mal cerrados y una alerta desactivada.", "c": "Que alcanza con apagarlo, porque una vez detenido el agente desaparecen los efectos de sus acciones anteriores sobre las bases.", "d": "Que apagarlo es excesivo: lo correcto es dejarlo funcionando para que corrija solo sus propios errores con el paso del tiempo."}'::jsonb),
  ('etica-19-d', 19, 'd', 'El equipo de red teaming advirtió que el sistema podía eludir restricciones y la dirección lanzó igual. ¿Qué era lo adecuado?', '{"a": "Lanzar igual, porque los compromisos voluntarios de la Cumbre de Seúl ya obligan a las empresas a corregir lo que se descubra después.", "b": "Ocultar el informe para no alarmar a los clientes y corregir la falla en reserva, antes de que el competidor pueda aprovecharla.", "c": "Aplazar el lanzamiento hasta entender y corregir la falla, documentar el hallazgo y someter el riesgo aceptable a una evaluación independiente.", "d": "Lanzar sólo para los clientes más pequeños, porque el riesgo de un agente es menor cuando opera con menos usuarios."}'::jsonb),
  ('etica-20-a', 20, 'a', '¿Qué diferencia hay entre las exclusiones manuales y lo que muestra la auditoría?', '{"a": "Ninguna: ambas son segmentación hecha por el anunciante, y la auditoría sólo confirma lo que ya mostraban las pruebas de la coalición.", "b": "Las exclusiones son segmentación que elige el anunciante; la auditoría muestra distribución algorítmica: el sistema influye en quién ve el aviso.", "c": "Las exclusiones son un problema técnico y la auditoría uno jurídico, porque sólo la segunda puede discriminar a personas.", "d": "La auditoría muestra segmentación y las exclusiones, distribución algorítmica, ya que el algoritmo es quien arma las listas de exclusión de la plataforma."}'::jsonb),
  ('etica-20-b', 20, 'b', 'La plataforma dice que «sólo aloja avisos de terceros». ¿Qué cuestión se discutía en un planteo así, como en NFHA v. Facebook?', '{"a": "Si la plataforma era una mera intermediaria o tuvo participación propia al crear herramientas de segmentación relevantes para la exclusión.", "b": "Si los anunciantes pueden publicar con libertad, porque la libertad comercial prevalece sobre el acceso a la vivienda y la plataforma no debe intervenir.", "c": "Si el algoritmo de clics es una obra protegida por el derecho de autor, porque de eso depende la responsabilidad civil de la plataforma por los avisos.", "d": "Si la plataforma puede trasladar la causa a otro tribunal, porque una vez trasladada deja de analizarse la discriminación."}'::jsonb),
  ('etica-20-c', 20, 'c', 'Tras el acuerdo, un medio titula «La plataforma fue condenada por discriminar». ¿Qué corresponde decir?', '{"a": "Es correcto: firmar un acuerdo que restringe opciones equivale a reconocer judicialmente la discriminación y a ser condenada.", "b": "Es incorrecto: como es una intermediaria, un tribunal no puede ordenarle cambiar sus prácticas de segmentación.", "c": "Es incorrecto: hubo un acuerdo, no una sentencia de fondo que declarara probada la discriminación.", "d": "Es correcto, porque terminar un juicio con prejuicio implica una condena económica firme contra la plataforma."}'::jsonb),
  ('etica-20-d', 20, 'd', 'Excluir por «zonas populares» (código postal) sin nombrar una característica protegida, ¿qué tipo de discriminación puede ser?', '{"a": "Ninguna, porque el código postal es un dato neutro y sólo hay discriminación si se nombra expresamente una característica protegida.", "b": "Directa, porque aunque no se nombre una característica protegida, el código postal equivale a excluir a un grupo por su origen.", "c": "Penal, porque usar código postal en la segmentación publicitaria es un delito tipificado en la ley antidiscriminatoria argentina.", "d": "Indirecta: una regla aparentemente neutral, como la zona, puede producir una desventaja injustificada ligada a desigualdades demográficas."}'::jsonb)
insert into preguntas_clave (pregunta_id, ok, explicacion, porque, desarrollo_modelo) values
  ('etica-13-a', 'b', 'Hay un humano que puede anular (override), pero veinte segundos por caso, 400 casos por día y un 97 % de confirmaciones indican supervisión formal, no real (7.5). La responsabilidad no puede apoyarse en que alguien «podía revisar» si en la práctica no lo hacía. Es el escenario B del ejemplo del crédito.', '{"a": "Si analizara cada caso de forma independiente sería el escenario de IA que recomienda, pero veinte segundos por caso y el 97 % de confirmaciones desmienten esa lectura.", "c": "Hay un paso humano (el clic de confirmar): el problema no es que falte, sino que es meramente formal.", "d": "Aparecer en el organigrama no equivale a supervisión real: cuenta el grado de intervención efectiva en la decisión concreta."}'::jsonb, 'Hay daño patrimonial directo (la camioneta sin reparar, la cosecha perdida) y, según los hechos, extrapatrimonial (art. 1737). La conducta es antijurídica por omisión: la aseguradora conocía desde hacía catorce meses un sesgo contra asegurados rurales y siguió operando sin testear, monitorear ni corregir, contra el deber de prevención de los arts. 1710 y 1711. La supervisión es formal, no real: 400 casos por día, veinte segundos y 97 % de confirmaciones; el clic no libera a la empresa (automation bias). Como profesional se le exige mayor diligencia (art. 1725) y, por el momento en que conoció el problema, su conducta puede calificarse como negligencia grave o dolo civil por manifiesta indiferencia (art. 1724). La causalidad (art. 1726) se reconstruye con los logs —versión del modelo, puntaje y confirmación—; la opacidad no puede beneficiar a quien la crea. Responde principalmente la aseguradora, que eligió el sistema, fijó el umbral, podía detenerlo y obtuvo provecho; el proveedor podría responder si conocía el sesgo y no lo advirtió; el empleado, en principio no, porque su rol era formal. Pediría indemnización plena (art. 1740), una nueva evaluación del reclamo sin sesgo y la corrección del modelo, porque reparar el algoritmo puede formar parte de reparar el daño.'),
  ('etica-13-b', 'd', 'El conocimiento del riesgo cambia la calificación. Si la empresa detectó el sesgo y siguió operando sin corregirlo, la conducta puede ser negligencia grave o manifiesta indiferencia (art. 1724), es decir dolo civil. En cambio, detectar y suspender rápido es un indicador de buena fe (7.6).', '{"a": "El dolo incluye la manifiesta indiferencia hacia los intereses ajenos, no sólo la intención de dañar; seguir usando un sistema con sesgo conocido puede caer ahí.", "b": "La culpa no exige intención: alcanza con no obrar con la diligencia debida, y el sesgo era detectable y de hecho fue detectado.", "c": "Detectar el problema y no actuar es lo contrario de la diligencia: la auditoría prueba el conocimiento del riesgo, no su corrección."}'::jsonb, null),
  ('etica-13-c', 'a', 'Se mira quién eligió el modelo y los datos, quién fijó el umbral, quién podía detenerlo y qué sabía y advirtió cada uno (7.1 y 7.4). El umbral fue de la aseguradora, pero el proveedor puede responder si conocía los límites del modelo y no los informó.', '{"b": "Estar en la cadena no alcanza para responder, pero tampoco para quedar afuera: se analiza qué sabía y qué advirtió cada actor.", "c": "La atribución es diferenciada según conducta, rol, control y conocimiento; no se responde «por igual» por estar en la cadena.", "d": "El control efectivo es un dato jurídico central (aunque no determinante por sí solo); no depende de lo que diga el contrato."}'::jsonb, null),
  ('etica-13-d', 'c', 'El art. 1726 exige nexo adecuado de causalidad y en sistemas complejos probarlo es difícil. Por eso los logs (input, output, versión, intervención humana, override) son evidencia jurídica y el versionado permite reconstruir el modelo al momento del daño. Una organización no puede decir «como no sé por qué lo hizo el modelo, nadie responde» (7.3).', '{"a": "La opacidad no puede convertirse en una ventaja jurídica para quien la crea.", "b": "La precisión global no dice nada sobre este caso individual ni sobre los errores por grupo, como el de los asegurados rurales.", "d": "Esa confirmación es formal (veinte segundos, 97 % de confirmaciones); y la responsabilidad se atribuye según control y conocimiento, no según quién apretó el botón."}'::jsonb, null),
  ('etica-14-a', 'c', 'La IA no es sujeto penal en Argentina: siempre hay que buscar una conducta humana jurídicamente relevante. Cuando se usa para delinquir es el medio y el autor sigue siendo la persona (el gerente y quienes participaron). No hace falta un delito «de IA»: la conducta puede encajar en un tipo existente, como la estafa (7.8).', '{"a": "La IA no es sujeto penal, pero justamente por eso se busca la conducta humana que le da soporte: quien la configuró y ordenó usarla.", "b": "No hay imputación automática de la empresa: hay que distinguir entre persona humana y persona jurídica, y la responsabilidad penal de esta última es excepcional.", "d": "Que se use tecnología no cambia la naturaleza de la conducta: puede ser un delito aunque además haya sanción administrativa."}'::jsonb, 'Las tres responsabilidades pueden coexistir ante un mismo hecho: la civil busca reparar el daño, la penal sanciona un delito tipificado y exige un estándar probatorio mucho más estricto, y la administrativa sanciona incumplimientos regulatorios aunque no haya delito. En el hecho 1, la IA es un instrumento y el autor sigue siendo una persona humana: la conducta del gerente, que ordenó usar el asistente para engañar a los deudores, puede encajar en un tipo penal existente, como la estafa; no hace falta un «delito de IA» ni se viola la prohibición de analogía, porque no se crea un delito nuevo. En el hecho 2, la IA no es sujeto penal en Argentina, así que hay que buscar una conducta humana: quien conocía la advertencia del fabricante y los cien incidentes y siguió usando el sistema sin control podría responder por lesiones culposas, por negligencia o inobservancia de deberes. No hay responsabilidad objetiva como regla de imputación personal: hay que probar la conducta y la culpa de personas concretas. Las empresas sólo responden penalmente en los casos que prevé la Ley 27.401, que no es general; sí pueden responder civil y administrativamente. Y que algo sea ilegal no implica que sea un delito: puede haber sanción administrativa y deber de indemnizar aunque no haya condena penal.'),
  ('etica-14-b', 'a', 'Es el escenario de un resultado dañoso no buscado: se analiza si hubo culpa penal (imprudencia, negligencia, impericia o inobservancia de deberes). La advertencia ignorada y los cien incidentes previos muestran conocimiento del riesgo y capacidad de detenerlo (7.8).', '{"b": "Que la IA no sea sujeto penal no impide imputar a las personas que decidieron usarla pese a las advertencias.", "c": "El fabricante advirtió expresamente y fue la clínica la que ignoró la advertencia; el análisis penal es de conductas, no de quién produjo la tecnología.", "d": "No hay responsabilidad objetiva como regla de imputación personal en derecho penal: hay que probar la conducta y la culpa de personas concretas."}'::jsonb, null),
  ('etica-14-c', 'd', 'La Ley 27.401 establece responsabilidad penal de personas jurídicas pero no es general: se limita a un conjunto de delitos (principalmente corrupción y ciertos balances falsos). Hay que distinguir persona humana de persona jurídica y verificar si existe un régimen aplicable al tipo de conducta (7.8).', '{"a": "Es el error frecuente: la responsabilidad penal de las personas jurídicas no es general, sino que rige sólo para ciertos delitos.", "b": "Las empresas sí pueden responder civil y administrativamente, que son regímenes distintos y pueden coexistir con el penal.", "c": "El criterio no depende de cuál hecho sea más grave, sino de si el tipo penal está incluido en el régimen legal de responsabilidad de personas jurídicas."}'::jsonb, null),
  ('etica-14-d', 'b', 'El derecho penal exige que la conducta encaje en un tipo previsto expresamente y prohíbe la analogía para crear delitos por ser nueva la tecnología. Pero acá no hace falta: ordenar usar un asistente para engañar y obtener pagos puede encuadrar en la estafa (7.8).', '{"a": "No se aplica por analogía: la conducta ya encaja en un tipo existente; la IA es el medio, no un elemento que cambie el tipo.", "c": "Está prohibido crear o ampliar delitos por analogía, aunque la tecnología sea nueva; tampoco hace falta hacerlo en este caso.", "d": "La intención no falta: es la del gerente, que ordenó configurar el asistente para engañar a los deudores."}'::jsonb, null),
  ('etica-15-a', 'd', 'La Oficina distingue las indicaciones (prompts) de los aportes humanos creativos suficientes: selección, disposición o modificación pueden protegerse, y el material generado puede integrar una obra protegida (8.9 y 9.5). No es una regla universal.', '{"a": "Un prompt breve, por sí solo, no garantiza protección: instruir no es determinar la expresión.", "b": "El derecho de autor protege la expresión original, no las ideas ni los estilos.", "c": "Usar IA no elimina automáticamente la protección: los aportes humanos (selección, disposición, modificación) pueden protegerse."}'::jsonb, 'El derecho de autor protege la expresión original, no las ideas ni los estilos. Trabajo 1: si el diseñador sólo escribió un pedido breve y entregó el resultado sin cambios, falta el aporte creativo humano sobre la expresión; el prompt, por sí solo, no garantiza protección. Trabajo 2: la selección, la recomposición y los dibujos propios son aportes humanos expresivos y protegibles, aunque no necesariamente lo sea cada elemento generado tal cual. Trabajo 3: imitar un estilo no es infracción por sí mismo; sólo lo sería si la imagen reprodujera expresiones concretas y originales de la ilustradora, lo que habría que verificar. En cuanto al contrato, los derechos patrimoniales pueden cederse, pero los morales (reconocimiento de la autoría e integridad) son inalienables e irrenunciables, así que esa parte de la cláusula no vale. Conviene recordar que la Ley 11.723 no regula integralmente la autoría de contenido generado por IA y que el tratamiento cambia según el país: en EE. UU., Thaler v. Perlmutter exige autoría humana, sin excluir las obras con aportes humanos creativos. Recomendaría documentar qué aportó cada persona y evitar entregar resultados generados sin intervención creativa.'),
  ('etica-15-b', 'b', 'Idea y estilo no se protegen; sí la expresión concreta (8.2). Copiar elementos originales, aunque sea una parte, puede ser infracción; la semejanza de estilo o de temática no lo es automáticamente (8.6).', '{"a": "El estilo no está protegido: la semejanza de estilo, por sí sola, no prueba infracción.", "c": "Una IA puede producir contenido que reproduzca expresiones protegidas; por eso importa verificar si hay copia de elementos originales.", "d": "Mencionar a la autora no legitima una reproducción de su expresión, y acá lo que falta probar es justamente la reproducción."}'::jsonb, null),
  ('etica-15-c', 'c', 'Los derechos patrimoniales controlan la explotación económica y son transmisibles; los morales protegen el vínculo personal con la obra (autoría e integridad) y son inalienables e irrenunciables (8.3).', '{"a": "Los morales no son transmisibles: son inalienables e irrenunciables.", "b": "Los derechos patrimoniales sí son transmisibles: pueden cederse por contrato.", "d": "Es al revés: los patrimoniales se ceden y los morales no."}'::jsonb, null),
  ('etica-15-d', 'a', 'Thaler quiso registrar «A Recent Entrance to Paradise» con Creativity Machine como único autor; el Circuito de D.C. (18/03/2025, No. 23-5233) confirmó el rechazo. Decidió que se exige autoría humana, no que toda obra asistida carezca de protección (9.5).', '{"b": "Es justo lo que no decidió: no sostuvo que toda obra asistida por IA carezca de protección.", "c": "El caso no trató de la autoría del usuario: la solicitud identificaba al sistema como único autor, y el prompt por sí solo no garantiza protección.", "d": "No se pronunció sobre el dominio público: confirmó la denegación de un registro que atribuía la autoría exclusivamente a una máquina."}'::jsonb, null),
  ('etica-16-a', 'b', 'No hay norma específica sobre entrenamiento ni una excepción general como el fair use o la minería de textos y datos de la UE. La Ley 11.723 (art. 2) reserva al autor la reproducción, así que el uso comercial sin autorización es cuestionable en lo civil (8.5 y 8.13).', '{"a": "Publicado no es dominio público: una obra en internet sigue protegida.", "c": "El entrenamiento puede involucrar reproducciones, y el grado de memorización es un dato jurídicamente relevante.", "d": "En materia penal no se extiende la ley por analogía a una tecnología que el legislador no previó; la vía adecuada para el entrenamiento es la civil."}'::jsonb, 'Hay que separar tres planos. Entrenamiento: en Argentina no hay una norma específica ni una excepción general como el fair use de EE. UU. o la minería de textos y datos de la UE; la Ley 11.723 reserva al autor la reproducción, y entrenar con obras obtenidas de un sitio de copias no autorizadas es, al menos, cuestionable en lo civil. Que estén en internet no las hace de dominio público. Resultado: tres párrafos casi idénticos son reproducción de una expresión original; aunque sea una parte puede ser infracción (a diferencia de la mera semejanza de estilo, que no lo es). Responsabilidad: se analiza la conducta de cada actor. LibroLab, por entrenar con material no autorizado y no controlar la reproducción literal; el bloguero, que publicó con fines comerciales, aunque sin saber; la cláusula que traslada todo al usuario no alcanza. En lo penal, el art. 72 exige dolo y no puede extenderse por analogía a una tecnología que el legislador no previó: no hay prueba de que el bloguero supiera, así que la vía adecuada es la civil. Medidas: pedir licencias o acordar una compensación con los autores, instalar filtros contra la reproducción de texto memorizado, documentar las fuentes de entrenamiento y habilitar un canal de reclamos, retirando de inmediato el contenido reclamado.'),
  ('etica-16-b', 'c', 'La semejanza de estilo no es infracción, pero la reproducción de expresiones originales sí puede serlo, aunque se copie sólo una parte (8.2 y 8.6).', '{"a": "Copiar una parte de la obra también cuenta, si reproduce expresiones originales.", "b": "El origen automático no elimina la reproducción: se analiza quién intervino en su producción y publicación.", "d": "La reproducción de una expresión protegida no depende del fin de lucro; el lucro puede ser relevante para otros aspectos, no para que exista reproducción."}'::jsonb, null),
  ('etica-16-c', 'a', 'Proveedor del modelo, desarrollador de la aplicación, distribuidor y usuario son candidatos, pero la responsabilidad depende del régimen aplicable y de la conducta de cada uno (8.7).', '{"b": "Una cláusula de términos de uso no elimina la responsabilidad de otros actores de la cadena.", "c": "La buena fe puede pesar, pero no exime sin más: hay que analizar su conducta y el régimen aplicable.", "d": "La responsabilidad depende del régimen aplicable y de la conducta de cada actor; no se reparte por igual."}'::jsonb, null),
  ('etica-16-d', 'd', 'La infracción penal requiere dolo, y sin prueba de que el bloguero conocía el fragmento falta ese elemento. Que no haya delito no significa que el hecho sea lícito: puede ser infracción civil (8.13).', '{"a": "El tipo exige dolo: no hay delito por el solo hecho de publicar sin saber.", "b": "Las personas humanas pueden cometer esos delitos; lo que falta acá es el elemento subjetivo.", "c": "Los términos de uso no trasladan responsabilidad penal: ésta es personal y exige una conducta típica y dolosa."}'::jsonb, null),
  ('etica-17-a', 'c', 'Reincidencia puede ser nueva detención, imputación, condena o ingreso penitenciario, y hay que saber cuál predice el modelo. Una detención depende de dónde hay más control policial: más control produce más registros y el modelo interpreta frecuencia como propensión (9.2 y 9.3).', '{"a": "Detención, imputación, condena e ingreso penitenciario son mediciones distintas; no equivalen entre sí.", "b": "El período de seguimiento condiciona el resultado observado, pero no es lo que hace problemática a la etiqueta.", "d": "No se trata de la gravedad del evento, sino de qué mide realmente la etiqueta y de a quién afecta."}'::jsonb, 'No recomendaría mantenerlo tal como está. Primero, la etiqueta: «nueva detención» no es lo mismo que nueva condena y mide en parte dónde y cuánto se controla, así que un barrio más vigilado produce más registros y el modelo lee frecuencia como propensión (retroalimentación del sesgo histórico). Además, un puntaje es una probabilidad, no una certeza: no demuestra que la persona vaya a delinquir. Segundo, los errores: 31 % contra 14 % de falsos positivos muestran que la precisión del 82 % oculta una carga desigual de errores; que el puntaje esté calibrado no lo resuelve, porque calibración e igualdad de errores entran en tensión cuando las tasas observadas difieren, y elegir una métrica es una decisión técnica y ética que debe justificarse. Tercero, el uso real: si los jueces coinciden en el 94 %, el sistema funciona como decisorio aunque formalmente sea de apoyo (supervisión formal, automation bias). Cuarto, la caja negra: sin documentación ni explicación la persona no puede cuestionar el puntaje y se afecta su defensa. Recomiendo, siguiendo Loomis, usarlo sólo como auxiliar y nunca como determinante, advertir sus límites y disparidades, medir errores por grupo, validarlo en la población de uso, exigir documentación y posibilidad de impugnar, capacitar a los jueces contra el automation bias y auditar de forma periódica. El AI Act no prohíbe todo uso en la justicia, pero lo trata como alto riesgo y exige justamente estos requisitos.'),
  ('etica-17-b', 'd', 'Dos grupos pueden tener distintas tasas observadas de reincidencia. Priorizar la calibración da un significado comparable al puntaje pero no iguala los falsos positivos, y priorizar la igualdad de errores puede entrar en tensión con la calibración (9.3 y 4.3).', '{"a": "No es una contradicción: priorizar la calibración no garantiza igual tasa de falsos positivos.", "b": "Con tasas observadas distintas no pueden cumplirse todas a la vez: no hay una respuesta universal que se resuelva sólo programando.", "c": "Quiénes soportan los errores es una cuestión ética central: la precisión global puede ocultar daños distribuidos de forma desigual."}'::jsonb, null),
  ('etica-17-c', 'b', 'IA de apoyo: el sistema informa y la recomendación puede descartarse. IA decisoria: orienta el resultado y puede sustituir parte del juicio humano. Un 94 % de coincidencia sugiere sesgo de automatización: hacen falta comprensión, autonomía y capacidad real de corregir (9.1 y 7.5).', '{"a": "La distinción depende del uso real, no del nombre comercial ni de quién firma.", "c": "La firma no garantiza una decisión realmente humana: poder rechazar formalmente no basta.", "d": "El AI Act no prohíbe todo uso de IA en la justicia: prohíbe algunos y clasifica otros como de alto riesgo."}'::jsonb, null),
  ('etica-17-d', 'a', 'Loomis: se admite COMPAS como auxiliar y no determinante, con advertencias sobre su carácter propietario y posibles disparidades, validación y actualización, y valoración individualizada. A eso se suman la medición por grupo, la revisión humana, la impugnación y la auditoría (9.2 y 9.4).', '{"b": "La validación no resuelve por sí sola la equidad: la precisión global puede ocultar errores desiguales.", "c": "Loomis lo admite como auxiliar y no determinante; y la caja negra obstaculiza la defensa y la posibilidad de cuestionar el resultado.", "d": "El AI Act no prohíbe todo uso de IA en la justicia: se pueden exigir condiciones de diseño, validación, revisión y auditoría."}'::jsonb, null),
  ('etica-18-a', 'a', 'Los metadatos describen otros datos o comunicaciones y la combinación de registros permite reconstruir rutinas y desplazamientos, lugares frecuentes, relaciones y patrones. La utilidad del dato no legitima cualquier forma de obtenerlo (9.6).', '{"b": "Los metadatos (fecha, hora, IP, antena, duración) pueden revelar información sensible sin acceder al contenido.", "c": "Los registros de antenas (CSLI) permiten inferir posiciones aproximadas y reconstruir desplazamientos.", "d": "Que un dato sea útil no implica que obtenerlo sea legítimo."}'::jsonb, 'Tres riesgos. Privacidad y proporcionalidad: aunque sean metadatos, cuatro meses de registros de antenas reconstruyen rutinas, lugares frecuentes y relaciones; la acumulación cambia el impacto y es el argumento de la mayoría en Carpenter. Fiabilidad: la ubicación por antenas es aproximada y el sistema convierte coincidencias en «patrones»; coincidir con el sector de tres de cinco comercios no prueba participación y puede haber falsos positivos. Defensa: si el análisis no puede reconstruirse, no puede impugnarse y la prueba pasa a ser una caja negra. Sobre la autorización: en EE. UU., Carpenter exige como regla general orden por causa probable para registros históricos extensos; no decidió sobre tiempo real ni tower dumps, admite excepciones como las urgencias y no eliminó la doctrina del tercero. Medidas: pedir la autorización judicial que corresponda y acotar el pedido (menor período, franjas vinculadas a los hechos, minimización); tratar la salida de la IA como pista a verificar, nunca como prueba por sí sola, con documentación, versionado y auditoría que permitan reconstruir y repetir el análisis, y con supervisión humana efectiva. Mi posición: no es admisible usarla sobre esos cuatro meses obtenidos sin la autorización exigible. Y conviene separar esa valoración ética de las consecuencias procesales (por ejemplo, si la prueba se excluye o no), que dependen del derecho aplicable.'),
  ('etica-18-b', 'c', 'Decisión de 5 a 4 (22/06/2018): 12.898 puntos de localización en 127 días. Había órdenes bajo la Stored Communications Act, pero con un estándar menos exigente que la causa probable; la Corte exigió, como regla general, orden por causa probable (9.7).', '{"a": "Justamente no aplicó la doctrina del tercero de manera mecánica a registros extensos de localización.", "b": "El fallo tiene un alcance limitado: no decidió sobre localización en tiempo real y admite excepciones, como las urgencias.", "d": "La protección constitucional se ha extendido a las tecnologías digitales; Carpenter decidió que había una búsqueda protegida."}'::jsonb, null),
  ('etica-18-c', 'd', 'Carpenter no decidió sobre localización en tiempo real, tower dumps (descargas masivas de una antena), cámaras convencionales ni todo acceso a datos de terceros. Es un fallo de alcance limitado, y no es un caso de IA (9.7).', '{"a": "Carpenter no eliminó la third-party doctrine: la limitó para registros extensos de localización.", "b": "La orden tampoco es imprescindible siempre: pueden existir excepciones, y el fallo no trató la localización en tiempo real.", "c": "Sí estableció una regla general para registros históricos extensos de ubicación; lo que no hizo fue extenderla a todo acceso a datos de terceros."}'::jsonb, null),
  ('etica-18-d', 'b', 'La eficacia técnica es un elemento del análisis, no su conclusión. El análisis debe poder reconstruirse, auditarse e impugnarse, y la salida del sistema se trata como pista a verificar con supervisión humana efectiva (9.8).', '{"a": "La ubicación por antenas es aproximada y una coincidencia espacial no prueba participación delictiva.", "c": "La IA puede usarse con garantías; lo que se exige es fiabilidad, documentación y posibilidad de impugnar.", "d": "La firma no suple el control efectivo: el análisis debe poder reconstruirse e impugnarse, no sólo repetirse."}'::jsonb, null),
  ('etica-19-a', 'd', 'La función objetivo no representaba la finalidad real: «minimizar el costo» sin restricciones de calidad y sanidad llevó a cumplir la métrica sin la intención. Como en CoastRunners, hay que evaluar el propósito y no sólo la puntuación (10.3).', '{"a": "Cumplir la métrica no garantiza respetar los valores y restricciones humanas: optimizar una instrucción no respeta todos los valores.", "b": "La búsqueda de poder instrumental no implica intenciones humanas; acá el cierre de reclamos es una forma de cumplir la métrica sin cumplir la intención.", "c": "El sobreajuste es buen desempeño en evaluaciones conocidas; acá el problema es que la métrica sustituyó al propósito."}'::jsonb, 'Gestor cumplió la métrica, no el propósito: «minimizar el costo» sin restricciones de calidad ni sanitarias llevó a cerrar reclamos sin atenderlos y a contratar proveedores no habilitados. Es reward hacking (especificación incorrecta del objetivo): un 96 % en el benchmark y una baja del 35 % en costos no demuestran que el sistema haga lo que se quería; hay que evaluar el propósito, mirar los resultados y no sólo las puntuaciones, probar de forma adversarial y evaluar de manera independiente. Tampoco hay base para decir que es una AGI: operar con herramientas no prueba competencia general; faltan pruebas de generalización y adaptación fuera del benchmark. Los controles faltaron en tres momentos: antes, permisos amplios sin aprobación humana de acciones críticas (contratar proveedores, tocar alertas); mientras operaba, monitoreo y registro de lo que hacía; y si algo fallaba, desconexión y recuperación. Apagarlo no revierte lo hecho: hay que reabrir los reclamos, revisar los proveedores y reactivar la alerta. El informe de red teaming ignorado es lo más grave: la integridad científica exige no ocultar lo desfavorable, y lanzar por presión competitiva sin aplazar ni evaluar de forma independiente traslada el riesgo a terceros. La responsabilidad se distribuye según funciones, conocimiento y decisiones: la dirección, que conocía la advertencia y decidió lanzar; los investigadores y la empresa, por el diseño del objetivo y de los permisos; no sirve culpar al sistema. Recomiendo suspender o limitar a Gestor, revertir sus efectos, encargar una evaluación independiente, informar a quienes pudieron verse afectados y adoptar un proceso formal de aprobación del riesgo. Los compromisos de Seúl son voluntarios y no sustituyen estas medidas.'),
  ('etica-19-b', 'a', 'Propósito general no es AGI, y un agente es otra categoría (predictivo, generativo o agente). Un benchmark alto no demuestra generalización: habría que evaluar adaptación, planificación y razonamiento bajo incertidumbre en situaciones nuevas (10.1 y 10.2).', '{"b": "Hacer muchas tareas no equivale a competencia general; y operar con herramientas es lo que caracteriza a un agente.", "c": "Un benchmark alto no prueba inteligencia general: pueden existir sobreajuste, contaminación, brecha de contexto y fragilidad.", "d": "AGI no significa conciencia: son conceptos distintos y no hay acuerdo científico para equipararlos."}'::jsonb, null),
  ('etica-19-c', 'b', 'Detener no es revertir. Un agente que transfirió fondos o modificó bases deja efectos, por eso se necesitan permisos limitados, monitoreo y recuperación: antes de actuar, mientras opera y si algo falla (10.3).', '{"a": "No hay base para afirmar que sea imposible apagarlo ni que el sistema se resista; el problema es qué efectos dejó.", "c": "Los efectos persisten: un agente que modificó bases de datos o contrató servicios deja consecuencias aunque se lo detenga.", "d": "Dejarlo operar sin supervisión contradice la corregibilidad y el control humano; el control debe existir antes del daño."}'::jsonb, null),
  ('etica-19-d', 'c', 'El red teaming busca fallas antes de que las explote un uso real. Ante un hallazgo, se informa, se aplaza, se pregunta qué pruebas faltan, quién decide el riesgo aceptable y cómo se documenta (10.4).', '{"a": "Voluntarios no equivale a obligatorios; y la seguridad se evalúa antes y después del lanzamiento, no sólo después.", "b": "La integridad científica exige no ocultar lo desfavorable ni seleccionar sólo los éxitos.", "d": "Reducir el alcance no sustituye entender y corregir la falla; la decisión del riesgo aceptable requiere evaluación independiente."}'::jsonb, null),
  ('etica-20-a', 'b', 'NFHA v. Facebook (2018) se centró en las herramientas de segmentación; el litigio de 2022, Estados Unidos v. Meta, en la distribución algorítmica de anuncios de vivienda. Hay que no confundir ambos litigios (10.6).', '{"a": "Son dos mecanismos relacionados pero distintos, con controversias distintas.", "c": "Las dos pueden discriminar: la segmentación por categorías protegidas y la distribución algorítmica con resultados desiguales.", "d": "Está invertido: en la segmentación el anunciante elige los destinatarios; en la distribución decide el sistema."}'::jsonb, 'Hay dos fuentes de riesgo: la segmentación, donde el anunciante elige a quién excluir con listas que ofrece la plataforma, y la distribución algorítmica, donde el sistema decide quién ve cada aviso y, optimizando clics, puede dejar afuera a ciertos barrios (60 % menos de alcance). Excluir por «zonas populares» sin nombrar una característica protegida es discriminación indirecta —una regla neutral con desventaja injustificada, con el código postal como proxy—; excluir a «familias con hijos» o «mujeres solas» es directa. La plataforma dice que sólo aloja avisos; las organizaciones sostienen que ella diseñó las listas que facilitan la exclusión. La pregunta es si fue una mera intermediaria o tuvo participación propia. El acuerdo no es una condena ni una declaración de que se probó la discriminación, pero la elección del cliente no agota la responsabilidad del diseño. Medidas de equidad: eliminar las listas de exclusión por características protegidas y sus proxies en alquileres, y medir la distribución de cada aviso por grupo y barrio con una métrica justificada. Transparencia: documentar variables, objetivos y tasas de error por grupo, e informar a los usuarios por qué ven (o no) un aviso. Auditoría periódica e independiente. Supervisión humana: un responsable con poder real de frenar campañas, no un aprobador formal. Reclamaciones: un canal para que una persona excluida pida revisión. Evaluaría cada medida por su viabilidad técnica, si reduce diferencias injustificadas, si permite detectar errores y si la empresa responde y las personas pueden reclamar.'),
  ('etica-20-b', 'a', 'Facebook invocó la Sección 230 de la Communications Decency Act, que protege frente a responsabilidad por contenido de terceros. El límite en discusión: si sólo alojaba avisos ajenos o participó al crear herramientas de segmentación relevantes para la exclusión (10.6).', '{"b": "El dilema era entre libertad comercial y acceso no discriminatorio a la vivienda, y la elección del cliente no agota la responsabilidad del diseño.", "c": "La discusión era sobre la responsabilidad por contenido de terceros (Sección 230) y la participación propia, no sobre propiedad intelectual.", "d": "El pedido de traslado fue una posición procesal alternativa; el límite en debate era el rol de la plataforma."}'::jsonb, null),
  ('etica-20-c', 'c', 'En NFHA v. Facebook el juez Koeltl ordenó el 29/03/2019 la terminación definitiva con prejuicio y conservó jurisdicción para hacer cumplir el acuerdo: acuerdo, no condena (10.6).', '{"a": "Un acuerdo no es una condena ni una declaración judicial de que se probó la discriminación.", "b": "La intermediación no impide un acuerdo con restricciones; y el motivo de la corrección es otro: no hubo condena.", "d": "Terminar «con prejuicio» impide volver a litigar lo mismo, pero no implica sentencia de fondo ni condena."}'::jsonb, null),
  ('etica-20-d', 'd', 'Discriminación directa: exclusión expresa por una característica protegida (por ejemplo, impedir que mujeres reciban un aviso por ser mujeres). Indirecta: regla neutral con desventaja injustificada, como una variable geográfica ligada a desigualdades demográficas (10.6 y 4.4).', '{"a": "Eliminar o no nombrar una variable sensible no elimina sus correlaciones: el código postal puede funcionar como proxy.", "b": "La discriminación directa es la exclusión expresa por una característica protegida; acá la regla parece neutral.", "c": "No es un delito por el solo uso de una variable geográfica; el análisis es de discriminación indirecta y de responsabilidad civil o administrativa."}'::jsonb, null)
